namespace March7thHoney.Data.Custom;

/// <summary>
///     Config/Custom/WarpStoryGates.json, generated by scripts/generate-warp-data.py: for each game version with
///     new Trailblaze story, the main missions of its chapters, and the chapter gates of
///     ServerOption.Warps.StoryByChapter. The server has no chapter data of its own.
/// </summary>
public class WarpStoryGatesConfig
{
    public List<WarpStoryGate> Gates { get; set; } = [];

    // Ordered by version, then story order within a version.
    public List<WarpChapterGate> ChapterGates { get; set; } = [];
}

public class WarpStoryGate
{
    // "1.0", "2.7", ... A player has reached it once any of MainMissions is accepted or finished.
    public string Version { get; set; } = "";
    public List<string> Chapters { get; set; } = [];
    public List<int> MainMissions { get; set; } = [];
}

/// <summary>
///     Banner phases that open with one story chapter instead of with their whole version (StoryByChapter). Reached
///     once any of MainMissions is accepted or finished, once a later chapter gate is reached, or once the player has
///     reached a version newer than <see cref="Version" />.
/// </summary>
public class WarpChapterGate
{
    // Phase keys "{Version}-{Phase}" of Banners.history.json, e.g. "1.0-1".
    public List<string> Phases { get; set; } = [];
    public string Version { get; set; } = "";
    public int ChapterId { get; set; }
    public string Chapter { get; set; } = "";
    public List<int> MainMissions { get; set; } = [];
}

/// <summary>
///     Config/Custom/WarpItemNames.json, generated by scripts/generate-warp-data.py: character and light cone names
///     per admin language ("en", "zh-CN") for the admin Warps page.
/// </summary>
public class WarpItemNamesConfig
{
    public Dictionary<string, Dictionary<int, string>> Names { get; set; } = [];
}
